rollback.sql:
DELETE FROM ingest_item ii
 WHERE ii.kind = 'e2e'
   AND ii.source_kind = 'portal-oct'
   AND EXISTS (SELECT 1 FROM retinal_inference_job j
                WHERE j.ingest_item_id = ii.ingest_item_id);
UPDATE retinal_inference_job SET ingest_item_id = NULL;

changeSet.sql:
CREATE UNIQUE INDEX ux_retinal_job_ingest_item_task
    ON retinal_inference_job (ingest_item_id, task)
 WHERE ingest_item_id IS NOT NULL AND status <> 'cancelled';

DROP INDEX IF EXISTS ux_retinal_inference_job_e2e_sha256_scan_task_idx;

